class DeterministicRankListFake:
    """Return stable Qdrant-shaped points without importing Qdrant."""

    def search(self, query_id: str, *, limit: int = 50) -> list[dict]:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
            raise ValueError("limit must be a non-negative integer")
        record_ids = _RANKS.get(query_id, ())[:limit]
        return [
            {
                "id": record_id,
                "payload": {
                    "content_hash": _CONTENT_HASHES[record_id],
                    "model_id": MODEL_ID,
                    "projection_generation": PROJECTION_GENERATION,
                    "record_id": record_id,
                    "workspace_id": WORKSPACE_ID,
                },
                "score": 1.0 - (rank * 0.01),
            }
            for rank, record_id in enumerate(record_ids, 1)
        ]
